-- Seed modules, lessons, and questions for SmartDrive Naija
-- Only inserts if modules table is empty

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM modules) = 0 THEN

    -- ============================================================
    -- MODULE 1: Road Signs & Signals (Free)
    -- ============================================================
    VALUES ('road-signs', 'Road Signs & Signals', 'Learn all Nigerian road signs, traffic signals, and their meanings. Essential for safe driving and passing your theory test.', 'SignpostBig', 1, true, false, 45, 500);


    (1, 'warning-signs', 'Warning Signs', '# Warning Signs\n\nWarning signs alert drivers to potential hazards or changes in road conditions ahead. They are typically triangular with a red border.\n\n## Common Warning Signs in Nigeria\n\n### Road Condition Warnings\n- **Bend Ahead** — Triangle with curved arrow\n- **Uneven Surface** — Triangle with bumpy road\n- **Slippery Road** — Triangle with car skidding\n- **Narrow Bridge** — Triangle showing bridge narrowing\n\n### Hazard Warnings\n- **Pedestrian Crossing** — Triangle with walking person\n- **School Zone** — Triangle with children\n- **Cattle Crossing** — Triangle with cow\n- **Falling Rocks** — Triangle with rocks\n\n### Junction Warnings\n- **Crossroads Ahead** — Triangle with cross\n- **T-Junction** — Triangle with T shape\n- **Y-Junction** — Triangle with Y shape\n- **Roundabout Ahead** — Triangle with circular arrows\n\n> **Tip**: When you see a warning sign, reduce your speed and be prepared to stop. Warning signs give you time to react safely.\n\n## Key Takeaways\n1. Triangular signs are warning signs\n2. They alert you to hazards ahead\n3. Always slow down when you see them\n4. They are not regulatory but ignoring them can be dangerous', 2, 15, 50, false, 15, NULL),

    (1, 'informational-signs', 'Informational Signs', '# Informational Signs\n\nInformational signs provide useful information to drivers about directions, distances, and services. They are typically rectangular.\n\n## Types of Informational Signs\n\n### Direction Signs\n- Show the direction to nearby towns and cities\n- Usually green or blue rectangles\n- Include distance information\n\n### Service Signs\n- **Hospital** — Sign with "H" or cross\n- **Fuel Station** — Sign with fuel pump\n- **Rest Area** — Sign with tree or bench\n- **Police Station** — Sign with police badge\n\n### Tourist Information\n- Brown signs indicating tourist attractions\n- Historical sites\n- National parks\n\n## Key Takeaways\n1. Rectangular signs are informational\n2. They help with navigation\n3. Green signs are for directions\n4. Blue signs indicate services', 3, 10, 50, false, 10, NULL);

    -- Questions for Module 1

    -- ============================================================
    -- MODULE 2: Traffic Rules & Regulations (Free)
    -- ============================================================
    VALUES ('traffic-rules', 'Traffic Rules & Regulations', 'Master Nigerian traffic laws, right-of-way rules, speed limits, and FRSC regulations. Critical for safe and legal driving.', 'ShieldCheck', 2, true, false, 60, 600);


    (2, 'right-of-way', 'Right of Way Rules', '# Right of Way Rules\n\nUnderstanding right of way is essential for safe driving. It determines who proceeds first in different traffic situations.\n\n## Basic Right of Way Rules\n\n### At Intersections\n1. **At a T-junction**: Traffic on the major road has right of way\n2. **At a crossroads without signs**: Give way to traffic from the right\n3. **At a roundabout**: Give way to traffic already in the roundabout\n4. **At a controlled intersection**: Follow traffic lights or police signals\n\n### Emergency Vehicles\n- Always give way to emergency vehicles (ambulances, fire trucks, police)\n- Pull over to the left when you hear sirens\n- Do not block intersections for emergency vehicles\n\n### Pedestrians\n- Pedestrians at zebra crossings always have right of way\n- Slow down near school zones\n- Be prepared to stop for pedestrians at intersections\n\n> **Important**: Right of way is not a privilege — it is a responsibility. Even when you have right of way, you should exercise caution and be prepared to yield if necessary to avoid an accident.\n\n## Key Takeaways\n1. At roundabouts, give way to traffic already inside\n2. Emergency vehicles always have priority\n3. Pedestrians at zebra crossings have right of way\n4. At T-junctions, major road traffic has priority', 2, 20, 60, false, 20, NULL),

    (2, 'lane-discipline', 'Lane Discipline & Overtaking', '# Lane Discipline & Overtaking\n\nProper lane discipline and safe overtaking are crucial for road safety.\n\n## Lane Discipline\n\n### On Multi-Lane Roads\n- **Right lane**: For overtaking and faster traffic\n- **Left lane**: For normal driving\n- **Center lane**: For intermediate speeds\n- Always use your indicators when changing lanes\n\n### On Single-Lane Roads\n- Keep to the left side of the road\n- Do not straddle lane markings\n- Be aware of oncoming traffic\n\n## Safe Overtaking\n\n### Before Overtaking\n1. Check your mirrors and blind spots\n2. Ensure you have a clear view of the road ahead\n3. Make sure there is enough space to complete the maneuver\n4. Signal your intention\n\n### During Overtaking\n1. Accelerate briskly to pass quickly\n2. Keep a safe distance from the vehicle being overtaken\n3. Do not exceed the speed limit\n\n### After Overtaking\n1. Signal before moving back to the left\n2. Ensure you can see the overtaken vehicle in your mirror\n3. Move back to the left lane smoothly\n\n> **Dangerous**: Never overtake on a bend, at a junction, near a pedestrian crossing, or when visibility is poor. These are leading causes of head-on collisions in Nigeria.\n\n## Key Takeaways\n1. Keep left unless overtaking\n2. Always check blind spots before changing lanes\n3. Never overtake on bends or at junctions\n4. Signal before and after overtaking', 3, 20, 60, false, 20, NULL);

    -- Questions for Module 2

    -- ============================================================
    -- MODULE 3: Vehicle Maintenance (Free)
    -- ============================================================
    VALUES ('vehicle-maintenance', 'Vehicle Maintenance', 'Learn essential vehicle maintenance checks, routine servicing, and how to keep your vehicle roadworthy and safe.', 'Wrench', 3, true, false, 40, 400);


    (3, 'engine-care', 'Engine Care & Servicing', '# Engine Care & Servicing\n\nRegular engine maintenance extends the life of your vehicle and prevents breakdowns.\n\n## Oil Changes\n\n### When to Change Oil\n- Every 5,000 km or 3 months (whichever comes first)\n- Check oil level monthly using the dipstick\n- Use the recommended oil grade for your vehicle\n\n### Signs of Oil Problems\n- Oil warning light on dashboard\n- Dark, dirty oil on dipstick\n- Engine running louder than normal\n- Burning smell from engine\n\n## Coolant System\n\n- Check coolant level monthly\n- Top up with correct coolant mixture\n- Never open radiator cap when engine is hot\n- Watch for temperature gauge rising above normal\n\n## Air Filter\n\n- Replace every 20,000 km or annually\n- A clogged air filter reduces fuel efficiency\n- Check during every service\n\n> **Important**: Regular servicing by a qualified mechanic is essential. Delaying servicing can lead to costly repairs and dangerous failures.\n\n## Key Takeaways\n1. Change oil every 5,000 km or 3 months\n2. Check coolant monthly\n3. Replace air filter annually\n4. Never ignore warning lights on the dashboard', 2, 15, 50, false, 15, NULL),

    (3, 'brake-safety', 'Brake Safety', '# Brake Safety\n\nYour vehicle''s braking system is its most important safety feature.\n\n## Brake System Components\n\n1. **Brake pads** — Create friction to slow the vehicle\n2. **Brake discs/rotors** — Surface that pads press against\n3. **Brake fluid** — Transmits force from pedal to brakes\n4. **Brake lines** — Carry fluid to each wheel\n\n## Signs of Brake Problems\n\n- **Squeaking or grinding noise** — Worn brake pads\n- **Soft or spongy pedal** — Air in brake lines or low fluid\n- **Vehicle pulls to one side** — Uneven brake wear\n- **Longer stopping distance** — Worn pads or contaminated fluid\n- **Brake warning light** — System problem detected\n\n## Brake Maintenance\n\n- Check brake fluid level monthly\n- Replace brake pads every 40,000-50,000 km\n- Have brakes inspected at every service\n- Replace brake fluid every 2 years\n\n> **Critical**: Never drive with faulty brakes. If you notice any brake problems, stop driving immediately and have your vehicle towed to a mechanic.\n\n## Key Takeaways\n1. Brakes are your most important safety system\n2. Check brake fluid monthly\n3. Replace pads every 40,000-50,000 km\n4. Never ignore grinding noises or soft pedals', 3, 10, 50, false, 10, NULL);

    -- Questions for Module 3

    -- ============================================================
    -- MODULE 4: Defensive Driving (Premium)
    -- ============================================================
    VALUES ('defensive-driving', 'Defensive Driving', 'Advanced techniques for anticipating hazards, maintaining safe following distances, and driving defensively in all conditions.', 'Car', 4, false, true, 50, 700);


    (4, 'hazard-perception', 'Hazard Perception', '# Hazard Perception\n\nHazard perception is the ability to identify potential dangers on the road before they become emergencies.\n\n## Types of Hazards\n\n### Static Hazards\n- Road junctions\n- Pedestrian crossings\n- School zones\n- Narrow bridges\n- Road construction\n\n### Dynamic Hazards\n- Other vehicles changing lanes\n- Pedestrians stepping onto the road\n- Animals crossing\n- Cyclists\n- Parked cars with doors opening\n\n### Environmental Hazards\n- Wet or slippery roads\n- Fog reducing visibility\n- Sun glare\n- Potholes\n- Flooding\n\n## Scanning Technique\n\n1. **Look ahead** — Scan 12-15 seconds ahead\n2. **Check mirrors** — Every 5-8 seconds\n3. **Check blind spots** — Before changing direction\n4. **Watch for clues** — Ball rolling into road (child may follow), exhaust from parked car (door may open)\n\n> **Pro Tip**: Experienced drivers don''t just watch the car in front — they watch 2-3 cars ahead to anticipate what the car in front will do.\n\n## Key Takeaways\n1. Scan 12-15 seconds ahead\n2. Check mirrors every 5-8 seconds\n3. Watch for both static and dynamic hazards\n4. Anticipate what other road users might do', 2, 20, 60, false, 20, NULL),

    (4, 'night-driving', 'Night Driving Safety', '# Night Driving Safety\n\nDriving at night presents unique challenges that require extra caution.\n\n## Challenges of Night Driving\n\n1. **Reduced visibility** — Headlights illuminate only a limited distance\n2. **Glare** — Oncoming headlights can temporarily blind you\n3. **Fatigue** — Natural drowsiness increases at night\n4. **Impaired drivers** — More likely to be on the road at night\n5. **Wildlife** — Animals are more active at dawn and dusk\n\n## Safe Night Driving Practices\n\n### Before Driving\n- Ensure all headlights and taillights are working\n- Clean windshield and mirrors\n- Get enough rest before long night trips\n\n### While Driving\n- Use high beams on unlit roads (dip for oncoming traffic)\n- Reduce speed — you can only see as far as your headlights\n- Increase following distance\n- Take breaks every 2 hours\n- Never drive if feeling drowsy\n\n### Dealing with Glare\n- Look to the left edge of the road when meeting oncoming traffic\n- Avoid looking directly at headlights\n- Use anti-glare settings on your rearview mirror\n\n> **Warning**: Driving while drowsy is as dangerous as drunk driving. If you feel sleepy, pull over safely and rest.\n\n## Key Takeaways\n1. Reduce speed at night — you can only see as far as your headlights\n2. Use high beams on unlit roads but dip for oncoming traffic\n3. Increase following distance\n4. Never drive when drowsy — pull over and rest', 3, 15, 60, false, 15, NULL);

    -- Questions for Module 4

    -- ============================================================
    -- MODULE 5: Alcohol & Driving (Premium)
    -- ============================================================
    VALUES ('alcohol-driving', 'Alcohol & Drug Awareness', 'Understand the effects of alcohol and drugs on driving ability, legal limits, and the consequences of impaired driving in Nigeria.', 'Wine', 5, false, true, 35, 450);


    (5, 'drug-impairment', 'Drug Impairment & Driving', '# Drug Impairment & Driving\n\nBoth prescription and recreational drugs can impair your ability to drive safely.\n\n## Types of Drugs That Affect Driving\n\n### Prescription Drugs\n- **Antihistamines** — Can cause drowsiness\n- **Painkillers** — May affect reaction time\n- **Antidepressants** — Can cause dizziness\n- **Sleeping pills** — Residual drowsiness\n\n### Recreational Drugs\n- **Cannabis** — Slows reaction time, impairs coordination\n- **Cocaine** — Aggressive driving, poor judgment\n- **Opioids** — Extreme drowsiness, loss of focus\n\n## Warning Signs of Impairment\n\n- Drowsiness or fatigue\n- Dizziness or lightheadedness\n- Blurred or double vision\n- Difficulty concentrating\n- Delayed reactions\n\n## What to Do\n\n1. **Read labels** — Check if medication causes drowsiness\n2. **Ask your doctor** — Whether it is safe to drive\n3. **Do not mix** — Alcohol and drugs amplify effects\n4. **Use alternative transport** — If impaired, do not drive\n\n> **Law**: Driving under the influence of drugs is illegal in Nigeria and carries severe penalties including fines, imprisonment, and license revocation.\n\n## Key Takeaways\n1. Both prescription and recreational drugs can impair driving\n2. Always read medication labels for drowsiness warnings\n3. Never mix alcohol and drugs\n4. Driving under the influence of drugs is illegal', 2, 15, 50, false, 15, NULL);

    -- Questions for Module 5

    -- ============================================================
    -- MODULE 6: Emergency Handling (Free)
    -- ============================================================
    VALUES ('emergency-handling', 'Emergency Handling', 'Learn how to handle road emergencies, accidents, breakdowns, and first aid basics. Essential knowledge for every driver.', 'AlertTriangle', 6, true, false, 35, 450);


    (6, 'vehicle-breakdown', 'Vehicle Breakdown Safety', '# Vehicle Breakdown Safety\n\nA vehicle breakdown can be dangerous if not handled correctly.\n\n## What to Do During a Breakdown\n\n### On a Highway\n1. **Turn on hazard lights** immediately\n2. **Move to the shoulder** if possible\n3. **Stay in the vehicle** with seatbelts on\n4. **Call for help** — roadside assistance or FRSC\n5. **Place warning triangle** 45 meters behind vehicle\n\n### If You Cannot Move to the Shoulder\n1. Turn on hazard lights\n2. Place warning triangle behind vehicle\n3. Move all passengers to safety behind the barrier\n4. Do not stand behind or in front of the vehicle\n\n### At Night\n1. Keep hazard lights on\n2. Use a flashlight if available\n3. Stay visible but away from traffic\n4. Wait inside the vehicle if it is safe\n\n> **Warning**: Never try to repair your vehicle on the traffic side of the road. Always work on the side away from traffic.\n\n## Key Takeaways\n1. Turn on hazard lights immediately\n2. Move to the shoulder if possible\n3. Place warning triangle 45 meters behind\n4. Never work on the traffic side of the vehicle', 2, 10, 50, false, 10, NULL),

    (6, 'first-aid-basics', 'First Aid Basics for Drivers', '# First Aid Basics for Drivers\n\nBasic first aid knowledge can help you save lives at an accident scene.\n\n## Essential First Aid Skills\n\n### Stopping Bleeding\n1. Apply firm pressure with a clean cloth\n2. Elevate the wound if possible\n3. Do not remove embedded objects — apply pressure around them\n4. Add more cloth on top if blood soaks through\n\n### Checking Breathing\n1. Look for chest movement\n2. Listen for breathing sounds\n3. Feel for breath on your cheek\n4. If not breathing, begin CPR if trained\n\n### Treating Shock\n1. Lay the person flat on their back\n2. Elevate legs 15-20 cm (unless fractured)\n3. Cover with a blanket or coat\n4. Do not give food or water\n5. Reassure the person\n\n### Burns\n1. Cool with running water for 20 minutes\n2. Do not apply creams or ointments\n3. Cover with clean, non-fluffy cloth\n4. Do not break blisters\n\n> **Important**: Always call for professional medical help first. First aid is to stabilize the person until help arrives.\n\n## Emergency Numbers in Nigeria\n- **FRSC**: 122\n- **Police**: 199 or 112\n- **Emergency**: 112\n\n## Key Takeaways\n1. Apply pressure to stop bleeding\n2. Check breathing and perform CPR if trained\n3. Treat shock by laying person flat and elevating legs\n4. Always call for professional help first', 3, 10, 50, false, 10, NULL);

    -- Questions for Module 6

    -- ============================================================
    -- MODULE 7: Mock Test (Free, special slug)
    -- ============================================================
    VALUES ('mock-test', 'Mock Theory Test', 'Practice with FRSC-style questions covering all topics. 40 questions, 30 minutes — just like the real test.', 'FileCheck', 7, true, false, 30, 300);

    -- No lessons for mock test module — it uses questions from all modules

    RAISE NOTICE 'Seed data inserted successfully';
  ELSE
    RAISE NOTICE 'Modules already exist, skipping seed';
  END IF;
END $$;
