    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (1, 'regulatory-signs', 'Regulatory Signs', '# Regulatory Signs\n\nRegulatory signs are traffic signs that instruct road users on what they must or must not do. They are typically circular with a red border.\n\n## Types of Regulatory Signs\n\n### Prohibitory Signs\nThese signs prohibit certain actions:\n- **No Entry** — Red circle with white horizontal bar\n- **No Parking** — Red circle with diagonal line through "P"\n- **No U-Turn** — Red circle with U-turn crossed out\n- **Speed Limit** — Red circle with number indicating max speed in km/h\n\n### Mandatory Signs\nThese signs indicate actions that must be taken:\n- **Keep Left/Right** — Blue circle with arrow\n- **Roundabout Ahead** — Blue circle with rotating arrows\n- **Minimum Speed** — Blue circle with number\n\n### Priority Signs\n- **Give Way** — Inverted triangle\n- **Stop** — Red octagon\n\n> **Important**: Disobeying regulatory signs is a traffic offence under the FRSC Act and can result in fines or license points.\n\n## Key Takeaways\n1. Circular signs with red borders are regulatory\n2. They are enforceable by law\n3. Always reduce speed when you see regulatory signs\n4. Ignorance of signs is not a valid excuse', 1, 15, 50, false, 15, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (1, 1, 'road-signs', 'multiple_choice', 'What shape are regulatory signs in Nigeria?', '["Circular","Triangular","Rectangular","Diamond"]', 0, 'Regulatory signs are typically circular with a red border. They instruct road users on what they must or must not do.', 1, true),
    (1, 1, 'road-signs', 'multiple_choice', 'What does a red octagon sign mean?', '["Give Way","Stop","No Entry","Speed Limit"]', 1, 'A red octagon means STOP. You must come to a complete stop and only proceed when it is safe to do so.', 1, true),
    (1, 1, 'road-signs', 'multiple_choice', 'Which sign prohibits parking?', '["Blue circle with P","Red circle with diagonal line through P","Yellow triangle with P","Green rectangle with P"]', 1, 'A red circle with a diagonal line through "P" is the No Parking sign. Parking in such areas can result in a fine.', 1, true),
    (1, 2, 'road-signs', 'multiple_choice', 'What shape are warning signs?', '["Circular","Triangular","Rectangular","Octagonal"]', 1, 'Warning signs are typically triangular with a red border. They alert drivers to potential hazards ahead.', 1, true),
    (1, 2, 'road-signs', 'multiple_choice', 'What does a triangle with children indicate?', '["Playground ahead","School zone","Children crossing","No children allowed"]', 2, 'A triangle with children indicates a school zone. Drivers should slow down and watch for children crossing the road.', 1, true),
    (1, 2, 'road-signs', 'multiple_choice', 'When you see a warning sign, you should:', '["Speed up","Maintain speed","Reduce speed and be prepared","Stop immediately"]', 2, 'Warning signs alert you to hazards ahead. You should reduce speed and be prepared to react safely.', 1, true),
    (1, 3, 'road-signs', 'multiple_choice', 'What color are directional information signs?', '["Red","Green","Yellow","Brown"]', 1, 'Directional information signs are typically green. They show directions to nearby towns and cities.', 1, true),
    (1, 3, 'road-signs', 'multiple_choice', 'What does a brown information sign indicate?', '["Hospital","Tourist attraction","Fuel station","Police station"]', 1, 'Brown signs indicate tourist attractions, historical sites, and national parks.', 1, true),
    (1, NULL, 'road-signs', 'multiple_choice', 'A blue circle with a rotating arrow means:', '["No entry","Roundabout ahead","Turn left","U-turn allowed"]', 1, 'A blue circle with rotating arrows indicates a roundabout ahead. Drivers should prepare to give way to traffic already in the roundabout.', 2, true),
    (1, NULL, 'road-signs', 'multiple_choice', 'Ignorance of road signs is:', '["A valid excuse","Not a valid excuse","Only valid for new drivers","Valid in rural areas"]', 1, 'Ignorance of road signs is not a valid excuse under the FRSC Act. All drivers are expected to know and understand road signs.', 2, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (2, 'speed-limits', 'Speed Limits in Nigeria', '# Speed Limits in Nigeria\n\nSpeed limits are set to ensure road safety for all users. In Nigeria, different road types have different speed limits.\n\n## Standard Speed Limits\n\n| Road Type | Speed Limit |\n|-----------|------------|\n| Urban areas | 50 km/h |\n| Highways | 100 km/h |\n| Expressways | 120 km/h |\n| School zones | 30 km/h |\n| Residential areas | 30 km/h |\n\n## Factors Affecting Safe Speed\n\n1. **Weather conditions** — Reduce speed in rain or fog\n2. **Traffic density** — Slow down in heavy traffic\n3. **Road conditions** — Potholes and uneven surfaces\n4. **Time of day** — Be extra cautious at night\n5. **Pedestrian activity** — Watch for people crossing\n\n> **FRSC Rule**: Exceeding the speed limit by more than 20 km/h can result in a fine of ₦3,000 and 3 penalty points on your license.\n\n## Key Takeaways\n1. Always observe posted speed limits\n2. Reduce speed in adverse conditions\n3. School zones require extra caution (30 km/h)\n4. Speeding is one of the leading causes of accidents in Nigeria', 1, 20, 60, false, 20, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (2, 1, 'traffic-rules', 'multiple_choice', 'What is the speed limit in urban areas in Nigeria?', '["40 km/h","50 km/h","60 km/h","80 km/h"]', 1, 'The speed limit in urban areas in Nigeria is 50 km/h. This helps ensure safety for pedestrians and other road users in built-up areas.', 1, true),
    (2, 1, 'traffic-rules', 'multiple_choice', 'What is the speed limit on Nigerian expressways?', '["80 km/h","100 km/h","120 km/h","140 km/h"]', 2, 'The speed limit on Nigerian expressways is 120 km/h. Always check for posted speed limits as they may vary.', 1, true),
    (2, 1, 'traffic-rules', 'multiple_choice', 'What is the speed limit in school zones?', '["20 km/h","30 km/h","40 km/h","50 km/h"]', 1, 'The speed limit in school zones is 30 km/h. Children may cross unexpectedly, so extra caution is needed.', 1, true),
    (2, 2, 'traffic-rules', 'multiple_choice', 'At a roundabout, who has right of way?', '["The vehicle entering","Traffic already in the roundabout","The larger vehicle","The faster vehicle"]', 1, 'Traffic already in the roundabout has right of way. Vehicles entering must give way to traffic already circulating.', 1, true),
    (2, 2, 'traffic-rules', 'multiple_choice', 'When an emergency vehicle approaches with sirens, you should:', '["Speed up to get out of the way","Pull over to the left and stop","Continue at the same speed","Stop immediately in your lane"]', 1, 'When an emergency vehicle approaches, pull over to the left and stop if safe. This allows the emergency vehicle to pass quickly and safely.', 1, true),
    (2, 2, 'traffic-rules', 'multiple_choice', 'At a zebra crossing, who has right of way?', '["The driver","The pedestrian","The larger vehicle","Whoever arrived first"]', 1, 'Pedestrians always have right of way at zebra crossings. Drivers must slow down and stop to let pedestrians cross safely.', 1, true),
    (2, 3, 'traffic-rules', 'multiple_choice', 'On a multi-lane road, which lane should you use for normal driving?', '["Right lane","Center lane","Left lane","Any lane"]', 2, 'The left lane is for normal driving. The right lane is for overtaking and faster traffic. Always keep left unless overtaking.', 1, true),
    (2, 3, 'traffic-rules', 'multiple_choice', 'When is it dangerous to overtake?', '["On a straight road","On a bend","In good weather","On a wide road"]', 1, 'Overtaking on a bend is extremely dangerous because you cannot see oncoming traffic. Never overtake on bends, at junctions, or near pedestrian crossings.', 1, true),
    (2, NULL, 'traffic-rules', 'multiple_choice', 'Exceeding the speed limit by more than 20 km/h in Nigeria can result in:', '["A warning only","A fine and penalty points","License suspension","No penalty"]', 1, 'Exceeding the speed limit by more than 20 km/h can result in a fine of ₦3,000 and 3 penalty points on your license under FRSC regulations.', 2, true),
    (2, NULL, 'traffic-rules', 'multiple_choice', 'Before changing lanes, you should:', '["Just signal and move","Check mirrors and blind spots, then signal","Honk and move","Speed up and cut in"]', 1, 'Always check your mirrors and blind spots, then signal before changing lanes. This ensures you are aware of other vehicles and communicate your intention.', 1, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (3, 'daily-checks', 'Daily Vehicle Checks', '# Daily Vehicle Checks\n\nBefore driving, you should perform basic checks to ensure your vehicle is safe.\n\n## The POWDERY Checklist\n\n**P** — **Petrol/Fuel**: Check fuel level\n**O** — **Oil**: Check engine oil level\n**W** — **Water**: Check coolant and windshield washer\n**D** — **Damage**: Check for visible damage\n**E** — **Electrics**: Check lights, indicators, horn\n**R** — **Rubber**: Check tire condition and pressure\n**Y** — **Yourself**: Ensure you are fit to drive\n\n## Tire Safety\n\n### Tire Pressure\n- Check pressure when tires are cold\n- Recommended pressure is usually 30-35 PSI\n- Under-inflated tires reduce fuel efficiency and can burst\n- Over-inflated tires reduce grip\n\n### Tire Tread\n- Minimum legal tread depth is 1.6mm\n- Worn tires are dangerous, especially on wet roads\n- Check for cuts, bulges, or embedded objects\n\n> **Safety Tip**: A tire blowout at high speed can cause loss of control. Check your tires regularly — it could save your life.\n\n## Key Takeaways\n1. Use the POWDERY checklist daily\n2. Check tire pressure and tread regularly\n3. Ensure all lights are working\n4. Never drive with damaged or worn tires', 1, 15, 50, false, 15, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (3, 1, 'vehicle-maintenance', 'multiple_choice', 'What does the "P" in POWDERY checklist stand for?', '["Pressure","Petrol/Fuel","Parts","Park"]', 1, 'In the POWDERY checklist, "P" stands for Petrol/Fuel. Always check your fuel level before starting a journey.', 1, true),
    (3, 1, 'vehicle-maintenance', 'multiple_choice', 'What is the minimum legal tire tread depth?', '["1.0mm","1.6mm","2.0mm","3.0mm"]', 1, 'The minimum legal tire tread depth is 1.6mm. Worn tires with less tread are dangerous, especially on wet roads.', 1, true),
    (3, 1, 'vehicle-maintenance', 'multiple_choice', 'When should you check tire pressure?', '["When tires are hot","When tires are cold","After driving 10km","Anytime"]', 1, 'Tire pressure should be checked when tires are cold. Heat from driving increases pressure and gives inaccurate readings.', 1, true),
    (3, 2, 'vehicle-maintenance', 'multiple_choice', 'How often should you change engine oil?', '["Every 1,000 km","Every 5,000 km or 3 months","Every 10,000 km","Once a year"]', 1, 'Engine oil should be changed every 5,000 km or 3 months, whichever comes first. This keeps the engine lubricated and prevents wear.', 1, true),
    (3, 2, 'vehicle-maintenance', 'multiple_choice', 'When should you replace the air filter?', '["Every 5,000 km","Every 20,000 km or annually","Every 50,000 km","Never"]', 1, 'The air filter should be replaced every 20,000 km or annually. A clogged air filter reduces fuel efficiency and engine performance.', 1, true),
    (3, 3, 'vehicle-maintenance', 'multiple_choice', 'A squeaking noise when braking usually means:', '["Brakes are working well","Brake pads are worn","Brake fluid is low","Nothing serious"]', 1, 'A squeaking or grinding noise when braking usually means the brake pads are worn and need replacement. Have them checked immediately.', 1, true),
    (3, 3, 'vehicle-maintenance', 'multiple_choice', 'How often should brake fluid be replaced?', '["Every 6 months","Every 2 years","Every 5 years","Never"]', 1, 'Brake fluid should be replaced every 2 years. Old brake fluid can absorb moisture, reducing braking effectiveness.', 1, true),
    (3, NULL, 'vehicle-maintenance', 'multiple_choice', 'If the brake warning light comes on, you should:', '["Continue driving","Stop and have the vehicle checked","Ignore it if brakes feel normal","Drive slowly to your destination"]', 1, 'If the brake warning light comes on, stop driving immediately and have the vehicle checked. Driving with faulty brakes is extremely dangerous.', 1, true),
    (3, NULL, 'vehicle-maintenance', 'multiple_choice', 'Under-inflated tires can cause:', '["Better fuel efficiency","Reduced fuel efficiency and potential blowout","Better grip","No issues"]', 1, 'Under-inflated tires reduce fuel efficiency and can overheat, leading to a blowout. Always maintain correct tire pressure.', 2, true),
    (3, NULL, 'vehicle-maintenance', 'multiple_choice', 'Never open the radiator cap when:', '["The engine is cold","The engine is hot","The vehicle is parked","In the morning"]', 1, 'Never open the radiator cap when the engine is hot. The cooling system is under pressure and can spray boiling coolant, causing severe burns.', 2, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (4, 'following-distance', 'Safe Following Distance', '# Safe Following Distance\n\nMaintaining a safe following distance is one of the most important defensive driving skills.\n\n## The 3-Second Rule\n\n1. Watch the vehicle ahead pass a fixed point (e.g., a sign or pole)\n2. Count "one thousand one, one thousand two, one thousand three"\n3. If you reach the point before finishing counting, you are too close\n\n## Adjusting Following Distance\n\n| Condition | Following Distance |\n|-----------|-------------------|\n| Normal conditions | 3 seconds |\n| Wet roads | 4-5 seconds |\n| Fog or heavy rain | 5-6 seconds |\n| Behind large vehicles | 4-5 seconds |\n| At high speeds | 4+ seconds |\n\n## Why Following Distance Matters\n\n- Gives you time to react to sudden stops\n- Provides space for emergency maneuvers\n- Reduces the risk of rear-end collisions\n- Allows for brake failure margin\n\n> **Fact**: Rear-end collisions are among the most common accidents in Nigeria, often caused by following too closely.\n\n## Key Takeaways\n1. Use the 3-second rule in normal conditions\n2. Increase distance in bad weather\n3. Keep extra distance behind large vehicles\n4. Never tailgate — it is dangerous and illegal', 1, 15, 60, false, 15, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (4, 1, 'defensive-driving', 'multiple_choice', 'What is the recommended following distance in normal conditions?', '["1 second","2 seconds","3 seconds","5 seconds"]', 2, 'The recommended following distance in normal conditions is 3 seconds. Use the 3-second rule: count after the vehicle ahead passes a fixed point.', 1, true),
    (4, 1, 'defensive-driving', 'multiple_choice', 'On wet roads, your following distance should be:', '["2 seconds","3 seconds","4-5 seconds","6-7 seconds"]', 2, 'On wet roads, increase your following distance to 4-5 seconds. Wet roads increase stopping distance and reduce tire grip.', 1, true),
    (4, 2, 'defensive-driving', 'multiple_choice', 'How far ahead should you scan while driving?', '["5-8 seconds","8-10 seconds","12-15 seconds","20+ seconds"]', 2, 'You should scan 12-15 seconds ahead. This gives you time to identify and react to potential hazards before they become emergencies.', 1, true),
    (4, 2, 'defensive-driving', 'multiple_choice', 'How often should you check your mirrors?', '["Every 2-3 seconds","Every 5-8 seconds","Every 10-15 seconds","Only when changing lanes"]', 1, 'Check your mirrors every 5-8 seconds. Regular mirror checks help you stay aware of traffic around you.', 1, true),
    (4, 3, 'defensive-driving', 'multiple_choice', 'When driving at night, you should:', '["Drive at the same speed as daytime","Reduce speed — you can only see as far as your headlights","Drive faster to reach your destination","Use high beams at all times"]', 1, 'At night, reduce your speed because you can only see as far as your headlights illuminate. This gives you time to react to hazards.', 1, true),
    (4, 3, 'defensive-driving', 'multiple_choice', 'When meeting oncoming traffic at night, you should:', '["Keep high beams on","Look to the left edge of the road","Close your eyes briefly","Speed up to pass quickly"]', 1, 'When meeting oncoming traffic at night, look to the left edge of the road to avoid being blinded by glare. Never use high beams when facing oncoming traffic.', 1, true),
    (4, NULL, 'defensive-driving', 'multiple_choice', 'Driving while drowsy is:', '["Safe if you open the window","As dangerous as drunk driving","Only dangerous on highways","Not a problem for experienced drivers"]', 1, 'Driving while drowsy is as dangerous as drunk driving. If you feel sleepy, pull over safely and rest. Do not try to push through.', 2, true),
    (4, NULL, 'defensive-driving', 'multiple_choice', 'A ball rolling into the road likely means:', '["Nothing","A child may follow","It is a game","The road is safe"]', 1, 'A ball rolling into the road is a clue that a child may follow. Always be prepared to stop when you see objects rolling into the road.', 2, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (5, 'alcohol-effects', 'Effects of Alcohol on Driving', '# Effects of Alcohol on Driving\n\nAlcohol significantly impairs your ability to drive safely, even in small amounts.\n\n## How Alcohol Affects Driving\n\n1. **Slower reaction times** — Takes longer to respond to hazards\n2. **Impaired judgment** — Riskier decisions and overconfidence\n3. **Reduced coordination** — Difficulty steering and braking\n4. **Poor vision** — Blurred vision and reduced depth perception\n5. **Drowsiness** — Increased risk of falling asleep at the wheel\n\n## Blood Alcohol Concentration (BAC)\n\n| BAC Level | Effects |\n|-----------|--------|\n| 0.02% | Some loss of judgment |\n| 0.05% | Reduced coordination |\n| 0.08% | Clear impairment |\n| 0.10% | Significant impairment |\n\n## Legal Limit in Nigeria\n\nThe legal BAC limit in Nigeria is **0.05%**. However, the FRSC recommends **zero tolerance** — do not drink any alcohol if you plan to drive.\n\n> **Important**: Even one drink can impair your driving. The safest choice is to not drink at all if you will be driving.\n\n## Key Takeaways\n1. Alcohol impairs reaction time, judgment, and coordination\n2. The legal BAC limit in Nigeria is 0.05%\n3. FRSC recommends zero tolerance\n4. Even small amounts of alcohol affect driving ability', 1, 15, 50, false, 15, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (5, 1, 'alcohol-driving', 'multiple_choice', 'What is the legal BAC limit for driving in Nigeria?', '["0.00%","0.05%","0.08%","0.10%"]', 1, 'The legal BAC limit in Nigeria is 0.05%. However, the FRSC recommends zero tolerance — do not drink if you plan to drive.', 1, true),
    (5, 1, 'alcohol-driving', 'multiple_choice', 'How does alcohol affect driving?', '["Improves reaction time","Has no effect if small amount","Slows reaction time and impairs judgment","Makes you more alert"]', 2, 'Alcohol slows reaction times, impairs judgment, reduces coordination, and causes poor vision. Even small amounts can affect driving ability.', 1, true),
    (5, 1, 'alcohol-driving', 'multiple_choice', 'What does FRSC recommend regarding alcohol and driving?', '["One drink is fine","Zero tolerance","Only beer is allowed","Drink after driving"]', 1, 'The FRSC recommends zero tolerance for alcohol when driving. The safest choice is to not drink at all if you will be driving.', 1, true),
    (5, 2, 'alcohol-driving', 'multiple_choice', 'Which prescription drugs can affect driving?', '["None","Antihistamines and painkillers","Only antibiotics","Vitamins"]', 1, 'Antihistamines, painkillers, antidepressants, and sleeping pills can all affect driving. Always read labels and ask your doctor if it is safe to drive.', 1, true),
    (5, 2, 'alcohol-driving', 'multiple_choice', 'Mixing alcohol and drugs:', '["Has no additional effect","Amplifies the effects","Is safe in small amounts","Only affects certain people"]', 1, 'Mixing alcohol and drugs amplifies their effects, making impairment much worse. Never mix alcohol and drugs before driving.', 2, true),
    (5, NULL, 'alcohol-driving', 'multiple_choice', 'Driving under the influence of drugs in Nigeria carries:', '["No penalty","A warning","Severe penalties including fines and imprisonment","Only a small fine"]', 2, 'Driving under the influence of drugs is illegal in Nigeria and carries severe penalties including fines, imprisonment, and license revocation.', 2, true),
    (5, NULL, 'alcohol-driving', 'multiple_choice', 'If your medication causes drowsiness, you should:', '["Drive anyway","Drive slowly","Use alternative transport","Drink coffee and drive"]', 2, 'If your medication causes drowsiness, use alternative transport. Do not drive while impaired, even by prescription medication.', 1, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
    INSERT INTO lessons (module_id, slug, title_en, content_en, sort_order, estimated_minutes, xp_reward, is_microlesson, estimated_duration_minutes, microlesson_order)
    VALUES
    (6, 'accident-response', 'Accident Response', '# Accident Response\n\nKnowing what to do at the scene of an accident can save lives.\n\n## Steps to Take at an Accident Scene\n\n### 1. Ensure Safety First\n- Stop your vehicle safely\n- Turn on hazard lights\n- Place warning triangle 45 meters behind the scene\n- Do not put yourself in danger\n\n### 2. Call for Help\n- Call FRSC: **122**\n- Call Police: **199** or **112**\n- Call ambulance if there are injuries\n- Provide clear location information\n\n### 3. Check for Injuries\n- Do not move seriously injured people\n- Check if they are breathing\n- Stop severe bleeding with clean cloth\n- Keep injured persons warm\n\n### 4. Do NOT\n- Do not move vehicles unless they block traffic dangerously\n- Do not give injured persons food or water\n- Do not remove helmets from motorcycle accident victims\n- Do not leave the scene until help arrives\n\n> **Legal Requirement**: Under Nigerian law, you must stop and render assistance if you are involved in or witness an accident. Failing to do so is an offence.\n\n## Key Takeaways\n1. Safety first — use hazard lights and warning triangle\n2. Call FRSC on 122 or 112 for emergencies\n3. Do not move seriously injured people\n4. It is a legal requirement to stop and help', 1, 15, 50, false, 15, NULL),
    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (6, 1, 'emergency-handling', 'multiple_choice', 'What is the FRSC emergency number?', '["199","122","911","999"]', 1, 'The FRSC emergency number is 122. Call this number for road accidents and emergencies in Nigeria.', 1, true),
    (6, 1, 'emergency-handling', 'multiple_choice', 'How far behind should you place a warning triangle?', '["10 meters","20 meters","45 meters","100 meters"]', 2, 'Place a warning triangle 45 meters behind your vehicle to give approaching drivers enough warning. This is especially important on highways.', 1, true),
    (6, 1, 'emergency-handling', 'multiple_choice', 'At an accident scene, you should:', '["Move injured people immediately","Do not move seriously injured people","Give them water","Remove their helmet"]', 1, 'Do not move seriously injured people unless they are in immediate danger. Moving them can worsen spinal or neck injuries.', 1, true),
    (6, 2, 'emergency-handling', 'multiple_choice', 'During a breakdown on a highway, you should:', '["Stand behind the vehicle","Stay in the vehicle with seatbelts on","Try to repair on the traffic side","Leave the vehicle and walk"]', 1, 'During a breakdown, stay in the vehicle with seatbelts on and hazard lights on. Call for help and wait for assistance.', 1, true),
    (6, 2, 'emergency-handling', 'multiple_choice', 'Where should you place the warning triangle during a breakdown?', '["5 meters behind","20 meters behind","45 meters behind","In front of the vehicle"]', 2, 'Place the warning triangle 45 meters behind your vehicle to give approaching drivers enough time to react.', 1, true),
    (6, 3, 'emergency-handling', 'multiple_choice', 'To stop severe bleeding, you should:', '["Apply ice","Apply firm pressure with a clean cloth","Wash with alcohol","Use a tourniquet immediately"]', 1, 'Apply firm pressure with a clean cloth to stop severe bleeding. Elevate the wound if possible and add more cloth if blood soaks through.', 1, true),
    (6, 3, 'emergency-handling', 'multiple_choice', 'When treating shock, you should:', '["Give the person water","Lay them flat and elevate legs","Make them walk around","Give them food"]', 1, 'To treat shock, lay the person flat on their back and elevate their legs 15-20 cm (unless fractured). Cover with a blanket and do not give food or water.', 1, true),
    (6, NULL, 'emergency-handling', 'multiple_choice', 'The general emergency number in Nigeria is:', '["999","911","112","111"]', 2, 'The general emergency number in Nigeria is 112. You can also call 122 for FRSC or 199 for police.', 1, true),
    (6, NULL, 'emergency-handling', 'multiple_choice', 'For burns, you should:', '["Apply butter or oil","Cool with running water for 20 minutes","Apply ice directly","Break any blisters"]', 1, 'For burns, cool with running water for 20 minutes. Do not apply creams, butter, or ice directly. Cover with clean cloth.', 2, true);
    INSERT INTO modules (slug, title_en, description_en, icon, sort_order, is_free, is_premium, estimated_minutes, xp_reward)
